WITH synthetic AS (SELECT id, cloudflare_image_id, regexp_replace(cloudflare_image_id, '-(leg|dup)-[0-9a-f]+$', '') AS true_cf_id FROM public.product_images WHERE deleted_at IS NULL AND cloudflare_image_id ~ '-(leg|dup)-[0-9a-f]+$'), with_canonical AS (SELECT s.id AS synth_id, c.id AS canonical_id FROM synthetic s JOIN public.product_images c ON c.cloudflare_image_id = s.true_cf_id AND c.deleted_at IS NULL AND c.id <> s.id) UPDATE public.product_images pi SET is_shared = true, canonical_image_id = w.canonical_id, last_modified_source = 'claude', updated_at = now() FROM with_canonical w WHERE pi.id = w.synth_id;;
